            { input: '781', expectation: { value: '78 1', country: 'Switzerland' } },
        ]);
    });

    it('change country selecting from dropdown', () => {
        runTest([
            { input: '', expectation: { value: '', country: 'United States' } },
            { select: 'Canada', expectation: { value: '', country: 'Canada' } },
